CREATE FILE FORMAT mixed_csv TYPE = CSV, TRIM_SPACE = TRUE NULL_IF = ('NULL', '');

CREATE FILE FORMAT mixed_json TYPE = JSON, TRIM_SPACE = TRUE NULL_IF = ('NULL', '');

CREATE FILE FORMAT mixed_avro TYPE = AVRO, TRIM_SPACE = TRUE NULL_IF = ('NULL', '');

CREATE FILE FORMAT mixed_orc TYPE = ORC, TRIM_SPACE = TRUE NULL_IF = ('NULL', '');

CREATE FILE FORMAT mixed_parquet TYPE = PARQUET, TRIM_SPACE = TRUE NULL_IF = ('NULL', '');

CREATE FILE FORMAT mixed_xml COMPRESSION = AUTO, TYPE = XML PRESERVE_SPACE = TRUE;
